package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

import org.eclipse.rdf4j.common.transaction.IsolationLevel;
import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

/**
 * Guard for the commit window between publishing a weakened predicate-object guarantee to the heap and advancing the
 * data revision: a query started inside that window (under NONE and SNAPSHOT_READ isolation) must not pair the new,
 * weaker guarantee with a packed plan proven at the old revision under the stronger guarantee (a finite
 * {@code "5"^^xsd:int} anchor would drop {@code "05"^^xsd:int}), neither for its own answer nor for plans cached for
 * later queries. It holds because the query's LMDB dataset takes the store read lock while it is created, before any
 * planning, so the query plans only after the revision has advanced.
 */
class LmdbGuaranteeWeakeningCommitWindowTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final String NS = "urn:ex:commit-window:";
	private static final IRI P = VF.createIRI(NS, "p");
	private static final IRI NAME = VF.createIRI(NS, "name");
	private static final String QUERY = "PREFIX : <" + NS + ">\n"
			+ "SELECT ?s ?n WHERE { ?s :p ?o . ?s :name ?n FILTER(?o = 5) }";

	@TempDir
	File dataDir;

	@ParameterizedTest(name = "isolation={0}")
	@ValueSource(strings = { "NONE", "SNAPSHOT_READ" })
	void queryPlannedInTheCommitWindowSeesTheWeakenedGuarantee(String isolationName) throws Exception {
		IsolationLevel isolation = "NONE".equals(isolationName) ? IsolationLevels.NONE
				: IsolationLevels.SNAPSHOT_READ;
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc"));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			try (SailRepositoryConnection connection = repository.getConnection()) {
				connection.begin(isolation);
				connection.add(VF.createIRI(NS, "a"), P, VF.createLiteral("5", XSD.INT));
				connection.add(VF.createIRI(NS, "a"), NAME, VF.createLiteral("A"));
				connection.commit();
			}
			for (int warm = 0; warm < 3; warm++) {
				assertThat(subjects(repository, isolation)).containsExactly(NS + "a");
			}

			TripleStore tripleStore = tripleStore(store);
			AtomicReference<Long> revisionBefore = new AtomicReference<>(tripleStore.getDataRevision());
			AtomicReference<String> windowState = new AtomicReference<>();
			AtomicReference<CompletableFuture<List<String>>> inWindow = new AtomicReference<>();
			AtomicReference<Thread> inWindowThread = new AtomicReference<>();
			tripleStore.durableCommitBarrierForTesting = () -> {
				if (inWindow.get() != null) {
					return;
				}
				CompletableFuture<List<String>> future = new CompletableFuture<>();
				Thread reader = new Thread(() -> {
					try {
						future.complete(subjects(repository, isolation));
					} catch (Throwable failure) {
						future.completeExceptionally(failure);
					}
				}, "commit-window-reader");
				inWindow.set(future);
				inWindowThread.set(reader);
				reader.start();
				// Give the reader the chance to plan while the heap already holds the weakened guarantee and the
				// data revision has not advanced; never join here, the writer still holds the store's write lock.
				long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(2);
				while (System.nanoTime() < deadline && !future.isDone()
						&& reader.getState() != Thread.State.BLOCKED && reader.getState() != Thread.State.WAITING
						&& reader.getState() != Thread.State.TIMED_WAITING) {
					Thread.onSpinWait();
				}
				// Precondition of the finding: inside the window the heap already holds the weakened guarantee while
				// the data revision has not advanced yet.
				windowState.set(tripleStore.getCachedRdfTermDomain(pId(store))
						.map(
								domain -> domain.has(RdfTermDomain.Fact.CANONICAL_INTEGER))
						.orElse(true)
						+ "|" + (tripleStore.getDataRevision() == revisionBefore.get()));
			};
			try (SailRepositoryConnection connection = repository.getConnection()) {
				connection.begin(isolation);
				connection.add(VF.createIRI(NS, "b"), P, VF.createLiteral("05", XSD.INT));
				connection.add(VF.createIRI(NS, "b"), NAME, VF.createLiteral("B"));
				connection.commit();
			} finally {
				tripleStore.durableCommitBarrierForTesting = null;
			}

			assertThat(inWindow.get()).as("the commit barrier must have started the in-window reader").isNotNull();
			assertThat(windowState.get())
					.as("inside the window the guarantee is weakened (no CANONICAL_INTEGER) and the revision is unchanged")
					.isEqualTo("false|true");
			List<String> inWindowRows = inWindow.get().get(60, TimeUnit.SECONDS);
			// The reader starts after mdb_txn_commit, so every read it performs sees b; a plan proven under the old
			// CANONICAL_INTEGER guarantee would anchor ?o on "5"^^xsd:int and drop b.
			assertThat(inWindowRows).as("query started inside the commit window (reader state after start: "
					+ inWindowThread.get().getState() + ")").containsExactly(NS + "a", NS + "b");
			for (int run = 0; run < 3; run++) {
				assertThat(subjects(repository, isolation)).as("run " + run + " after the commit")
						.containsExactly(NS + "a", NS + "b");
			}
		} finally {
			repository.shutDown();
		}
	}

	private static List<String> subjects(SailRepository repository, IsolationLevel isolation) {
		List<String> subjects = new ArrayList<>();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin(isolation);
			try (TupleQueryResult result = connection.prepareTupleQuery(QUERY).evaluate()) {
				while (result.hasNext()) {
					BindingSet bindings = result.next();
					subjects.add(bindings.getValue("s").stringValue());
				}
			}
			connection.commit();
		}
		subjects.sort(String::compareTo);
		return subjects;
	}

	private static long pId(LmdbStore store) {
		try {
			Field field = LmdbSailStore.class.getDeclaredField("valueStore");
			field.setAccessible(true);
			return ((ValueStore) field.get(store.getBackingStore())).getId(P);
		} catch (Exception e) {
			throw new IllegalStateException(e);
		}
	}

	private static TripleStore tripleStore(LmdbStore store) throws Exception {
		Field field = LmdbSailStore.class.getDeclaredField("tripleStore");
		field.setAccessible(true);
		return (TripleStore) field.get(store.getBackingStore());
	}
}
